INSERT INTO `news` (`id`, `userid`, `added`, `body`, `subject`) VALUES (6, 1, '2009-01-19 10:59:50', '[size=20]Голосуем за [url=http://toptracker.ru/details.php?id=76] трекер[/url] (раз в сутки)[/size]\r\n[color=red][size=30][url=http://forum.bt-star.ru/forum/viewtopic.php?id=2]Встреча пользователей трекера нажимаем[/url][/size][/color]\r\n\r\n[url=/forum]Форум[/url].\r\nЗаходим туда со своим паролем и ником от трекера.\r\nЕсли не получается войти то идем [url=my.php]сюда[/url] и обновляем пароль.', 'Новости трекера'),
