INSERT INTO `torrents` (`id`, `info_hash`, `name`, `filename`, `save_as`, `search_text`, `descr`, `ori_descr`, `image1`, `image2`, `category`, `size`, `added`, `type`, `numfiles`, `comments`, `views`, `hits`, `times_completed`, `leechers`, `seeders`, `last_action`, `last_reseed`, `visible`, `banned`, `owner`, `free`, `sticky`, `points`, `silverload`, `image3`, `image4`, `comment_lock`, `ontop`, `ratio`, `tags`, `ratingsum`, `numratings`, `moderated`, `moderatedby`, `moderatorname`, `multitracker`, `f_peers`, `f_seeders`, `announce_list`, `tracker_cache`, `karma`) VALUES (601, 0x32363562393333666133666463383537613664383937396464646261636331386664616265356462, 'Московская сага (2004) DVDRip', '[OpenSharing.Ru]moskovskaya-saga-2004-dvdrip.torrent', 'РњРѕСЃРєРѕРІСЃРєР°СЏ СЃР°РіР° (2004)', 'OpenSharing Ru moskovskaya saga 2004 dvdrip 2004 2004 DVDRip', '[b]Оригинальное название:[/b] Московская сага\r\n[b]Год выхода:[/b] 2004\r\n[b]Жанр:[/b] Драма\r\n[b]Режиссер:[/b] Дмитрий Барщевский\r\n[b]В ролях:[/b] Юрий Соломин, Инна Чурикова, Александр Балуев, Ольга Будина, Алексей Кортнев, Сергей Безруков\r\n\r\n[b]О фильме:[/b] Драма по одноименному роману-эпопее В.Аксенова.\r\nМосква. 1925 год. Профессор Градов, его жена Мэри, их дети - Нина, Никита и Кирилл - и многолетние друзья дома, родня московская и тифлисская, и те, кому еще предстоит войти в эту семью и историю, - все молоды и полны надежд. Многим надеждам предстоит сбыться, но история страны в 30-50-е не оставила шансов на безоблачную жизнь ни для кого...\r\n\r\n[u]О файле:[/u]\r\n[b]Качество:[/b] DVDRip\r\n[b]Язык (перевод):[/b] русский\r\n[b]Формат:[/b] AVI\r\n[b]Размер:[/b] 8,62 GB (1 - 22 серии)\r\n\r\n[b]Видео:[/b] DivX, ~ 1053 Кбит/с, 720x576\r\n[b]Аудио:[/b] MP3, 128 Кбит/с', '[b]Оригинальное название:[/b] Московская сага\r\n[b]Год выхода:[/b] 2004\r\n[b]Жанр:[/b] Драма\r\n[b]Режиссер:[/b] Дмитрий Барщевский\r\n[b]В ролях:[/b] Юрий Соломин, Инна Чурикова, Александр Балуев, Ольга Будина, Алексей Кортнев, Сергей Безруков\r\n\r\n[b]О фильме:[/b] Драма по одноименному роману-эпопее В.Аксенова.\r\nМосква. 1925 год. Профессор Градов, его жена Мэри, их дети - Нина, Никита и Кирилл - и многолетние друзья дома, родня московская и тифлисская, и те, кому еще предстоит войти в эту семью и историю, - все молоды и полны надежд. Многим надеждам предстоит сбыться, но история страны в 30-50-е не оставила шансов на безоблачную жизнь ни для кого...\r\n\r\n[u]О файле:[/u]\r\n[b]Качество:[/b] DVDRip\r\n[b]Язык (перевод):[/b] русский\r\n[b]Формат:[/b] AVI\r\n[b]Размер:[/b] 8,62 GB (1 - 22 серии)\r\n\r\n[b]Видео:[/b] DivX, ~ 1053 Кбит/с, 720x576\r\n[b]Аудио:[/b] MP3, 128 Кбит/с', '6010.jpg', '6010.jpg', 8, 9267095552, '2009-06-07 22:03:41', 'multi', 22, 0, 0, 0, 0, 0, 0, '2009-06-07 22:03:41', '0000-00-00 00:00:00', 'no', 'no', 1845, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, 'Драма', 0, 0, 'no', 0, '', 1, 70, 34, 'http://announce.freeexchange.ru:2710/announce\nhttp://announce.opensharing.ru:2710/announce\nhttp://tracker.prq.to/announce', 'announce.freeexchange.ru:27:16\nannounce.opensharing.ru:24:11\ntracker.prq.to:19:7', 0),
(602, 0x33626331353739626139626532333332356564396665653865666330653465353233373635643861, 'Moscow Racer (2009) PC', '[FreeExchange.Ru]Moscow_Racer_[2009___RUS___PC].torrent', '[KiLeR]MoscowRacer2009', 'FreeExchange Ru Moscow Racer 2009 RUS PC KiLeR MoscowRacer2009 Moscow Racer 2009 PC', '[b]Кряк:[/b] http://rapidshare.com/files/237786199/Moscow_Racer.exe.html\r\n[b]Особенности игры:[/b]\r\n* Moscow Racer - гоночный симулятор, сочетающий высокий реализм с широчайшими игровыми возможностями\r\n* Игроков ждут гонки в плотном потоке машин - среди легковушек, грузовиков, автобусов, правительственных кортежей...\r\n* Возможность “срезания” трасс по тротуарам, переулкам и т.п.\r\n* В игре множество трюковых ситуаций: прыжки через автовозы, пробивание заграждений, выезды на железную дорогу и т.п.\r\n* Реалистичная физика, базирующаяся на мировой технологии Ageia PhysiX™ и учитывающая более 50 параметров на каждую машину\r\n* Более 10 трасс в самых известных районах Москвы: Садовое кольцо, Кремлевские набережные, Кутузовский проспект, Третье кольцо, Рублевское шоссе - с подробной информацией об истории каждого района\r\n* Более 10 машин - от мощных бизнес-седанов до умопомрачительных суперкаров\r\n* Отображение до 100 машин в кадре с высоким качеством и детализацией - благодаря графическому движку V12 RG с технологией IntelliLOD\r\n* Специальный обучающий режим, в точности повторяющий реальный курс подготовки автогонщиков\r\n\r\n[b]Название:[/b] Moscow Racer\r\n[b]Год выхода:[/b] 2009\r\n[b]Жанр:[/b] Автосимулятор\r\n[b]Выпущено:[/b] Акелла\r\n[b]Язык:[/b] Русский\r\n[b]Размер:[/b] 6.37 GB\r\n\r\n[u]Системные требования:[/u]\r\n[b]Минимальные системные требования[/b]\r\n>Процессор Intel Pentium 4 2.4 ГГц или аналогичный\r\n>512 МБ оперативной памяти\r\n>2 Гб свободного дискового пространства\r\n>видеокарта c 256 Мб\r\n\r\n[b]Установка:[/b]\r\n1) Смонтировать образ с помощью Daemon Tools или Alcohol 120%\r\n2) Установить игру\r\n3) Играем', '[b]Кряк:[/b] http://rapidshare.com/files/237786199/Moscow_Racer.exe.html\r\n[b]Особенности игры:[/b]\r\n* Moscow Racer - гоночный симулятор, сочетающий высокий реализм с широчайшими игровыми возможностями\r\n* Игроков ждут гонки в плотном потоке машин - среди легковушек, грузовиков, автобусов, правительственных кортежей...\r\n* Возможность “срезания” трасс по тротуарам, переулкам и т.п.\r\n* В игре множество трюковых ситуаций: прыжки через автовозы, пробивание заграждений, выезды на железную дорогу и т.п.\r\n* Реалистичная физика, базирующаяся на мировой технологии Ageia PhysiX™ и учитывающая более 50 параметров на каждую машину\r\n* Более 10 трасс в самых известных районах Москвы: Садовое кольцо, Кремлевские набережные, Кутузовский проспект, Третье кольцо, Рублевское шоссе - с подробной информацией об истории каждого района\r\n* Более 10 машин - от мощных бизнес-седанов до умопомрачительных суперкаров\r\n* Отображение до 100 машин в кадре с высоким качеством и детализацией - благодаря графическому движку V12 RG с технологией IntelliLOD\r\n* Специальный обучающий режим, в точности повторяющий реальный курс подготовки автогонщиков\r\n\r\n[b]Название:[/b] Moscow Racer\r\n[b]Год выхода:[/b] 2009\r\n[b]Жанр:[/b] Автосимулятор\r\n[b]Выпущено:[/b] Акелла\r\n[b]Язык:[/b] Русский\r\n[b]Размер:[/b] 6.37 GB\r\n\r\n[u]Системные требования:[/u]\r\n[b]Минимальные системные требования[/b]\r\n>Процессор Intel Pentium 4 2.4 ГГц или аналогичный\r\n>512 МБ оперативной памяти\r\n>2 Гб свободного дискового пространства\r\n>видеокарта c 256 Мб\r\n\r\n[b]Установка:[/b]\r\n1) Смонтировать образ с помощью Daemon Tools или Alcohol 120%\r\n2) Установить игру\r\n3) Играем', '6020.jpg', '6020.jpg', 32, 6836003056, '2009-06-07 22:47:34', 'multi', 2, 0, 0, 0, 0, 0, 0, '2009-06-07 22:47:34', '0000-00-00 00:00:00', 'no', 'no', 1845, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, '', 0, 0, 'no', 0, '', 1, 0, 0, 'http://files.beef.ge/announce.php', 'files.beef.ge:0:0', 1);
INSERT INTO `torrents` (`id`, `info_hash`, `name`, `filename`, `save_as`, `search_text`, `descr`, `ori_descr`, `image1`, `image2`, `category`, `size`, `added`, `type`, `numfiles`, `comments`, `views`, `hits`, `times_completed`, `leechers`, `seeders`, `last_action`, `last_reseed`, `visible`, `banned`, `owner`, `free`, `sticky`, `points`, `silverload`, `image3`, `image4`, `comment_lock`, `ontop`, `ratio`, `tags`, `ratingsum`, `numratings`, `moderated`, `moderatedby`, `moderatorname`, `multitracker`, `f_peers`, `f_seeders`, `announce_list`, `tracker_cache`, `karma`) VALUES (603, 0x38306138323461326430393038383965633830303832643865643963313337656236653036336636, 'Корсары 3: Ветер Свободы (2009) PC', '[FreeExchange.Ru]Korsary_3_veter_svobody.exe_Full_version.exe.torrent', 'Korsary 3 veter svobody.exe Full version.exe', '[FreeExchange.Ru]Korsary_3_veter_svobody.exe_Full_version.exe Korsary 3 veter svobody.exe Full version.exe ', '[b]Год выпуска:[/b] 2009\r\n[b]Жанр:[/b] Arcade, RPG, Симуляторы\r\n[b]Разработчик:[/b] Seven Winds\r\n[b]Издательство:[/b] Seven Winds\r\n[b]Платформа:[/b] PC\r\n\r\n[b]Системные требования:[/b]\r\n&#9658;Система: Windows XP;\r\n&#9658;Процессор: 1,5 ГГц;\r\n&#9658;Память: 256 Мб;\r\n&#9658;Видео-карта: совместимая с DirectX 9 3D-видеокарта уровня GeForce 3 (кроме MX-серии) с 64 Мб ОЗУ;\r\n&#9658;Аудио-карта: совместимая с DirectX;\r\n&#9658;Жесткий диск: 4 Гб свободного места;\r\n&#9658;DirectX 9.0c.\r\n\r\n[b]Тип издания: [/b]пиратка\r\n[b]Язык интерфейса: [/b]только русский\r\n[b]Таблэтка:[/b] Не требуется\r\n\r\n[b]Описание:[/b]\r\nПолноценная игра Корсары 3: Ветер Свободы, содержащее в себе новую сюжетную линию, множество квестов, насыщающее игру всяческими событиями, возможностями. Теперь окружающий мир действительно насыщен. Куча маленьких генерируемый квестов (событий), в которых главный герой может принять участие. Это и золотые караваны, и вымогательство, и захват известной личности, и захват корабля, перевозящего большой груз, и многое, многое другое!\r\n\r\n[b]Доп. информация:[/b]\r\n1. При начале новой игры Вам предоставиться возможность с помощью интерфейса создать своего главного героя:\r\n1.1. Выбор из 5-ти подготовленных героев: Генри Морган, Натаниэль Хаук, Уильям Арчер, Блейз Шарп, Беатрис Шарп.\r\n1.2. Создание собственного персонажа - Выбор модели типа от Барменов до Нечисти, саморучный ввод имени и фамилии, а также выбор нации.\r\n2. Основного сюжета, как такового, нет, но имеются Английская национальная квестовая линейка, квестовая линейка за Береговое Братство, а также около 20-ти квестов. Кроме того, пока вы на службе Англии - вы не сможете перейти на службу к пиратам или другим державам, также как и будучи на службе у пиратов не сможете встать на службу Англии и других держав.\r\n\r\n[spoiler=[b]Некоторые изменения и нововведения:[/b]]\r\n3. Новые генерируемые квесты:\r\n3.1. Помощь Церкви;\r\n3.2. Помощь Коменданту тюрьмы;\r\n3.3. Перевозка предметов;\r\n3.4. Поиск предметов;\r\n3.5. Сопровождение корабля;\r\n3.6. Доставка груза;\r\n3.7. Доставка пассажира.\r\n4. Теперь окружающий мир действительно насыщен. Куча маленьких генерируемый квестов (событий), в которых главный герой может принять участие. Это и золотые караваны, и вымогательство, и захват известной личности, и захват корабля, перевозящего большой груз, и многое, многое другое! Обо всём этом читайте ниже.\r\n5. Ситуации в джунглях:\r\n5.1 При прогулке по джунглям вам может попаться раненый человек, которому можно помочь и получить маленькую награду или плюс в репутацию.\r\n5.2 Вы можете попробовать ограбить прохожего.\r\n5.3 Пиратские банды могут совершать на вас нападение и осуществлять попытки грабежа.\r\n6. Семнадцать новых кораблей.\r\n7. Переработанные характеристики кораблей.\r\n8. Переработанная система продажи кораблей на верфи. Чем выше ранг главного героя - тем лучше корабль он может приобрести.\r\n9. Абордаж более реалистичен, посредством добавления локации абордажа в виде двух сцеплённых кораблей.\r\n10. Изменён процесс абордажа. Теперь, чтобы захватить корабль нужно зачистить от врагов определённые локации. Для кораблей 7,6,5 класса - Верхняя палуба -> Каюта; для кораблей 4,3 класса Верхняя палуба -> Трюм -> Каюта; для кораблей 2,1 класса - Верхняя палуба -> Трюм -> Пушечная палуба -> Каюта.\r\n11. Изменён процесс захвата форта. Теперь после того, как вы уничтожите всех врагов в первой локации форта, вам предстоит сразиться ещё в двух.\r\n12. Разнообразие погоды. И вечером, и днём возможен дождь и крутые волны. Кроме того, добавлен один вариант утренней погоды, ресурсы для которой есть, но в игре не задействована.\r\n13. Джунгли на всех островах.\r\n14. Бухты на всех островах.\r\n15. Подземелья на всех островах.\r\n16. Катакомбы в каждом городе.\r\n17. В джунглях возможно встретить банды, вымогающие деньги, бандитов и простых прохожих.\r\n18. В подземельях и катакомбах добавлена нечисть.\r\n19. В колониях теперь открыто множество локаций домов, кроме пиратской колонии "Исла Мона". Практически в каждый дом можно зайти. Ночью, естественно, все дома закрыты.\r\n20. Возможность обыскивать сундуки в домах, магазинах, каютах и т.д.\r\n21. Добавлена локация "Тюрьма" на всех колониях, имеющих форт.\r\n22. Все бордели и дома ростовщиков открыты.\r\n23. Возможность функционирования борделя. В борделе в ущерб репутации у нации героя, можно получать опыт.\r\n24. Возможность взятия кредита и возможность отдать деньги в рост у ростовщика.\r\n25. Большое количество нового холодного оружия. Добавлено огнестрельное оружие Мушкет.\r\n26. Новые предметы, а именно драгоценности и идолы.\r\n27. Изменение в процессе обыска сундука - Если вы попались при обыске сундуке, появилась возможность откупиться, чтобы не портить репутацию у нации. Также, если денег не оказалось, при хорошей удаче, хозяин локации, в которой вы обыскивали сундук, может простить вас.\r\n28. На архипелаге живёт "Учитель", который за определённую сумму может повысить любое умение на одно очко!\r\n29. Учитель берёт очень дорого и не сидит в одном месте. Он путешествует время от времени по архипелагу. Случайный слух может дать информацию о его расположении.\r\n30. Переработанная обработка попадания предметов, холодного и огнестрельного оружия на прилавки. Теперь она зависит от уровня главного героя. Напрямую зависит от минимального уровня ношения определённого оружия и уровня главного героя.\r\n31. Переработанная перезарядка пистолета. Теперь имеется возможность стрелять не один раз.\r\n32. Теперь и в магазине можно купить предметы и оружие, а не только у уличных торговцев.\r\n33. Влияние предметов, в частности идолов, на умения персонажа.\r\n34. Возможность постройки и улучшения собственной колонии на одном из необитаемых островов.\r\n35. Мелкие игровые изменения. Например уменьшение расстояния между кораблями при выходе из карты в море.\r\n36. Исправлены некоторые ошибки оригинальных "Корсаров 3". Всяческие исправления интерфейса.\r\n37. Ускорение времени на суше, глобальной карте и т.д. Не рекомендуется сильно ускорять время в игре. Ускорение вызывается клавишей "R", а также клавишами "+" и "-".\r\n38. Озвучка некоторых команд.\r\n39. Генератор карт сокровищ. Карту возможно купить у людей, отдыхающих в таверне. Чем выше умение удача, тем выше шанс, что вы встретите торговца картой. Так же, от умения удача напрямую зависит ценность клада и возможность найти в кладе отличный клинок, пистолет, подзорную трубу, запертый сундук, золото и т.д.\r\n40. В сундуках и кладах вы можете найти предмет "Сундук". Сундук можно переносить только один. Нужно их открыть. Открыть их может за отдельную плату умелец, один на архипелаг. В сундуке находиться почти всё, от смертельной ловушки до нескольких тысяч пиастров. Откроете - узнаете.\r\n41. Генератор золотых караванов. Информация о нём получается у пьяниц в таверне и получается очень редко. Правда, чем выше умение удача, тем выше шанс, что информация попадётся. Подробности в игре.\r\n42. Отключены чит-коды.\r\n43. Опция "Мысли вслух". Используется, для того, чтобы начать штурм форта с суши и т.д. Опция "мысли вслух" вызывается через интерфейс.\r\n44. Добавлены лечебные зелья для восстановления здоровья.\r\n45. Возможность быстрого употребления лечебных зелий. Осуществляется нажатием клавиши "F".\r\n46. Немного переработана система фехтования, а именно наносимый и получаемый главным героем урон, который теперь зависит ещё и новых от перков.\r\n47. Добавлено четыре перка (способности). Это Навык основной защиты, Навык продвинутой защиты, Критический удар и Профессиональный фехтовальщик. Все они влияют на наносимый или получаемый главным героем урон при фехтовании.\r\n48. Церковь теперь посещают прихожане.\r\n49. В домах появились жильцы. Также, в домах могут встретиться продавцы карт.\r\n50. Добавлена возможность штурмовать форты с суши. Чтобы начать штурм необходимо иметь не менее 800 команды, вызвать функцию "Мысли" и выбрать нужный вариант диалога. Цепь локаций теперь следующая - Выход из колонии -> Город -> Резиденция. Чтобы получить добычу (выкуп), по прежнему нужно поговорить с губернатором.\r\n51. Возможность воровства. Шанс того, что вы попадётесь зависит от удачи. Чтобы произвести эту операцию, необходимо подойти к персонажу на близкое растояние и в списке команд в верхнем левом углу выбрать команду Воровство, после чего появится интерфейс Воровства, схожий с обыском сундука. Возможность обворовывать распространяется только на простых граждан на улице и в таверне.\r\n52. Добавлены разные варианты исхода событий при воровстве. Либо вам удалось обворовать незаметно, либо удалось обворовать, но вас всё таки заметили, либо вас заметили сразу.\r\n53. Добавлен перк "Ловкач", который позволит вам снизить шанс того, что вас поймают при краже, либо обыске сундуков.\r\n54. Возможность обыскивать трупы. Происходит это в следующем порядке - Вы убиваете персонажа, и сразу после убийства появляется интерфейс обыска трупов. Если его закрыть, то больше обыск только что убитого персонажа производиться не будет. К тому же, в этом варианте есть плюсы - всё происходит автоматически. Он выводиться только один раз. Есть возможность отключать или включать обыск трупов по ходу игры. Для этого нужно вызвать "мысли вслух", и в нужном варианте диалога выбрать вариант "Включить" или "Выключить". Если обыск отключен, его, собственно, не будет.\r\n55. Возможность обнаружить и забрать экипировку у убитого зависит от удачи.\r\n56. Добавлен перк "Опытный контрабандист", повышающий бонус к цене контрабандных товаров.\r\n57. Искуственная жизнь пиратов. Добавлены десять известных пиратов, которых можно будет встретить по игре. Список ситуаций, в которых участвуют эти пираты:\r\n58.1. Можно встретить в таверне.\r\n58.2. Можно встретить в море, у какого либо острова.\r\n58.3. Пират может напасть на главного героя в море.\r\n58.4. О каком-либо действии какого-либо пирата можно случайно узнать у прохожих или отдыхающих в тавернах.\r\n59. Возможность служить губернатору доступна только после завершения сюжетной линии!\r\n60. Добавлены кирасы. Чтобы их экипировать, необходимо иметь способность "Кирасы", а также требуемый ранг.\r\n61. Возможность вымогания денег. Работает в следующем порядке: При разговоре с алкашами в таверне, они могут проболтаться, что у одного из основных жителей колонии водятся большие деньги. И уже непосредственно идём к разбогатевшему хозяину таверны, магазина, верфи, или ростовщику. Шанс, что вам удасться выбить деньги зависит от ранга и вашей удачи и авторитета. В зависимости от этого испытуемый может позвать охрану, ничего не дать, или всё таки дать деньги.\r\n62. Всё холодное оружие разделено на лёгкое, среднее и тяжёлое. В зависимости от типа холодного оружия будет определятся наносимый урон, а также и расходуемая энергия.\r\n63. У любого хозяина таверны можно узнать очень интересную информацию. Естественно, не бесплатно. Причём информация может быть трёх видов. Возможность получить информацию зависит опять же, от удачи и авторитета.\r\n64. Добавлено множество музыки из игры "Пираты Карибского Моря", а также пара звуков.\r\n65. Случайное место начала игры. Генерируется в зависимости от выбранной нации.\r\n66. Выбранная нация при начале новой игры влияет только на начальное местоположение игрока.\r\n67. Иконки предметов преобразились.\r\n68. Тюрьмы теперь оправдывают своё название, т.к. теперь в них находятся заключённые. Это что то вроде декорации.\r\n69. В городах появились проводники, которые за грош могут проводить вас до нужного вам здания.\r\n70. В интерфейсе торговли предметами используйте вспомогательные клавиши для быстрой продажи или покупки товаров. "Alt" работает с 50 единицами, а "Shift" - со всем доступным товаром. Внимание - Только для продажи!\r\n71. Возможность пройтись по своему кораблю. При этом в трюме и пушечной палубе будет расхаживать ваши канониры и матросы, создающие необходимую атмосферу на корабле.\r\n... И ДРУГОЕ![/spoiler]\r\n\r\n[b]Установка и запуск:[/b]\r\n1.- Распаковать игру в нужную Вам директорию.\r\n2.- Играть.', '[b]Год выпуска:[/b] 2009\r\n[b]Жанр:[/b] Arcade, RPG, Симуляторы\r\n[b]Разработчик:[/b] Seven Winds\r\n[b]Издательство:[/b] Seven Winds\r\n[b]Платформа:[/b] PC\r\n\r\n[b]Системные требования:[/b]\r\n&#9658;Система: Windows XP;\r\n&#9658;Процессор: 1,5 ГГц;\r\n&#9658;Память: 256 Мб;\r\n&#9658;Видео-карта: совместимая с DirectX 9 3D-видеокарта уровня GeForce 3 (кроме MX-серии) с 64 Мб ОЗУ;\r\n&#9658;Аудио-карта: совместимая с DirectX;\r\n&#9658;Жесткий диск: 4 Гб свободного места;\r\n&#9658;DirectX 9.0c.\r\n\r\n[b]Тип издания: [/b]пиратка\r\n[b]Язык интерфейса: [/b]только русский\r\n[b]Таблэтка:[/b] Не требуется\r\n\r\n[b]Описание:[/b]\r\nПолноценная игра Корсары 3: Ветер Свободы, содержащее в себе новую сюжетную линию, множество квестов, насыщающее игру всяческими событиями, возможностями. Теперь окружающий мир действительно насыщен. Куча маленьких генерируемый квестов (событий), в которых главный герой может принять участие. Это и золотые караваны, и вымогательство, и захват известной личности, и захват корабля, перевозящего большой груз, и многое, многое другое!\r\n\r\n[b]Доп. информация:[/b]\r\n1. При начале новой игры Вам предоставиться возможность с помощью интерфейса создать своего главного героя:\r\n1.1. Выбор из 5-ти подготовленных героев: Генри Морган, Натаниэль Хаук, Уильям Арчер, Блейз Шарп, Беатрис Шарп.\r\n1.2. Создание собственного персонажа - Выбор модели типа от Барменов до Нечисти, саморучный ввод имени и фамилии, а также выбор нации.\r\n2. Основного сюжета, как такового, нет, но имеются Английская национальная квестовая линейка, квестовая линейка за Береговое Братство, а также около 20-ти квестов. Кроме того, пока вы на службе Англии - вы не сможете перейти на службу к пиратам или другим державам, также как и будучи на службе у пиратов не сможете встать на службу Англии и других держав.\r\n\r\n[spoiler=[b]Некоторые изменения и нововведения:[/b]]\r\n3. Новые генерируемые квесты:\r\n3.1. Помощь Церкви;\r\n3.2. Помощь Коменданту тюрьмы;\r\n3.3. Перевозка предметов;\r\n3.4. Поиск предметов;\r\n3.5. Сопровождение корабля;\r\n3.6. Доставка груза;\r\n3.7. Доставка пассажира.\r\n4. Теперь окружающий мир действительно насыщен. Куча маленьких генерируемый квестов (событий), в которых главный герой может принять участие. Это и золотые караваны, и вымогательство, и захват известной личности, и захват корабля, перевозящего большой груз, и многое, многое другое! Обо всём этом читайте ниже.\r\n5. Ситуации в джунглях:\r\n5.1 При прогулке по джунглям вам может попаться раненый человек, которому можно помочь и получить маленькую награду или плюс в репутацию.\r\n5.2 Вы можете попробовать ограбить прохожего.\r\n5.3 Пиратские банды могут совершать на вас нападение и осуществлять попытки грабежа.\r\n6. Семнадцать новых кораблей.\r\n7. Переработанные характеристики кораблей.\r\n8. Переработанная система продажи кораблей на верфи. Чем выше ранг главного героя - тем лучше корабль он может приобрести.\r\n9. Абордаж более реалистичен, посредством добавления локации абордажа в виде двух сцеплённых кораблей.\r\n10. Изменён процесс абордажа. Теперь, чтобы захватить корабль нужно зачистить от врагов определённые локации. Для кораблей 7,6,5 класса - Верхняя палуба -> Каюта; для кораблей 4,3 класса Верхняя палуба -> Трюм -> Каюта; для кораблей 2,1 класса - Верхняя палуба -> Трюм -> Пушечная палуба -> Каюта.\r\n11. Изменён процесс захвата форта. Теперь после того, как вы уничтожите всех врагов в первой локации форта, вам предстоит сразиться ещё в двух.\r\n12. Разнообразие погоды. И вечером, и днём возможен дождь и крутые волны. Кроме того, добавлен один вариант утренней погоды, ресурсы для которой есть, но в игре не задействована.\r\n13. Джунгли на всех островах.\r\n14. Бухты на всех островах.\r\n15. Подземелья на всех островах.\r\n16. Катакомбы в каждом городе.\r\n17. В джунглях возможно встретить банды, вымогающие деньги, бандитов и простых прохожих.\r\n18. В подземельях и катакомбах добавлена нечисть.\r\n19. В колониях теперь открыто множество локаций домов, кроме пиратской колонии "Исла Мона". Практически в каждый дом можно зайти. Ночью, естественно, все дома закрыты.\r\n20. Возможность обыскивать сундуки в домах, магазинах, каютах и т.д.\r\n21. Добавлена локация "Тюрьма" на всех колониях, имеющих форт.\r\n22. Все бордели и дома ростовщиков открыты.\r\n23. Возможность функционирования борделя. В борделе в ущерб репутации у нации героя, можно получать опыт.\r\n24. Возможность взятия кредита и возможность отдать деньги в рост у ростовщика.\r\n25. Большое количество нового холодного оружия. Добавлено огнестрельное оружие Мушкет.\r\n26. Новые предметы, а именно драгоценности и идолы.\r\n27. Изменение в процессе обыска сундука - Если вы попались при обыске сундуке, появилась возможность откупиться, чтобы не портить репутацию у нации. Также, если денег не оказалось, при хорошей удаче, хозяин локации, в которой вы обыскивали сундук, может простить вас.\r\n28. На архипелаге живёт "Учитель", который за определённую сумму может повысить любое умение на одно очко!\r\n29. Учитель берёт очень дорого и не сидит в одном месте. Он путешествует время от времени по архипелагу. Случайный слух может дать информацию о его расположении.\r\n30. Переработанная обработка попадания предметов, холодного и огнестрельного оружия на прилавки. Теперь она зависит от уровня главного героя. Напрямую зависит от минимального уровня ношения определённого оружия и уровня главного героя.\r\n31. Переработанная перезарядка пистолета. Теперь имеется возможность стрелять не один раз.\r\n32. Теперь и в магазине можно купить предметы и оружие, а не только у уличных торговцев.\r\n33. Влияние предметов, в частности идолов, на умения персонажа.\r\n34. Возможность постройки и улучшения собственной колонии на одном из необитаемых островов.\r\n35. Мелкие игровые изменения. Например уменьшение расстояния между кораблями при выходе из карты в море.\r\n36. Исправлены некоторые ошибки оригинальных "Корсаров 3". Всяческие исправления интерфейса.\r\n37. Ускорение времени на суше, глобальной карте и т.д. Не рекомендуется сильно ускорять время в игре. Ускорение вызывается клавишей "R", а также клавишами "+" и "-".\r\n38. Озвучка некоторых команд.\r\n39. Генератор карт сокровищ. Карту возможно купить у людей, отдыхающих в таверне. Чем выше умение удача, тем выше шанс, что вы встретите торговца картой. Так же, от умения удача напрямую зависит ценность клада и возможность найти в кладе отличный клинок, пистолет, подзорную трубу, запертый сундук, золото и т.д.\r\n40. В сундуках и кладах вы можете найти предмет "Сундук". Сундук можно переносить только один. Нужно их открыть. Открыть их может за отдельную плату умелец, один на архипелаг. В сундуке находиться почти всё, от смертельной ловушки до нескольких тысяч пиастров. Откроете - узнаете.\r\n41. Генератор золотых караванов. Информация о нём получается у пьяниц в таверне и получается очень редко. Правда, чем выше умение удача, тем выше шанс, что информация попадётся. Подробности в игре.\r\n42. Отключены чит-коды.\r\n43. Опция "Мысли вслух". Используется, для того, чтобы начать штурм форта с суши и т.д. Опция "мысли вслух" вызывается через интерфейс.\r\n44. Добавлены лечебные зелья для восстановления здоровья.\r\n45. Возможность быстрого употребления лечебных зелий. Осуществляется нажатием клавиши "F".\r\n46. Немного переработана система фехтования, а именно наносимый и получаемый главным героем урон, который теперь зависит ещё и новых от перков.\r\n47. Добавлено четыре перка (способности). Это Навык основной защиты, Навык продвинутой защиты, Критический удар и Профессиональный фехтовальщик. Все они влияют на наносимый или получаемый главным героем урон при фехтовании.\r\n48. Церковь теперь посещают прихожане.\r\n49. В домах появились жильцы. Также, в домах могут встретиться продавцы карт.\r\n50. Добавлена возможность штурмовать форты с суши. Чтобы начать штурм необходимо иметь не менее 800 команды, вызвать функцию "Мысли" и выбрать нужный вариант диалога. Цепь локаций теперь следующая - Выход из колонии -> Город -> Резиденция. Чтобы получить добычу (выкуп), по прежнему нужно поговорить с губернатором.\r\n51. Возможность воровства. Шанс того, что вы попадётесь зависит от удачи. Чтобы произвести эту операцию, необходимо подойти к персонажу на близкое растояние и в списке команд в верхнем левом углу выбрать команду Воровство, после чего появится интерфейс Воровства, схожий с обыском сундука. Возможность обворовывать распространяется только на простых граждан на улице и в таверне.\r\n52. Добавлены разные варианты исхода событий при воровстве. Либо вам удалось обворовать незаметно, либо удалось обворовать, но вас всё таки заметили, либо вас заметили сразу.\r\n53. Добавлен перк "Ловкач", который позволит вам снизить шанс того, что вас поймают при краже, либо обыске сундуков.\r\n54. Возможность обыскивать трупы. Происходит это в следующем порядке - Вы убиваете персонажа, и сразу после убийства появляется интерфейс обыска трупов. Если его закрыть, то больше обыск только что убитого персонажа производиться не будет. К тому же, в этом варианте есть плюсы - всё происходит автоматически. Он выводиться только один раз. Есть возможность отключать или включать обыск трупов по ходу игры. Для этого нужно вызвать "мысли вслух", и в нужном варианте диалога выбрать вариант "Включить" или "Выключить". Если обыск отключен, его, собственно, не будет.\r\n55. Возможность обнаружить и забрать экипировку у убитого зависит от удачи.\r\n56. Добавлен перк "Опытный контрабандист", повышающий бонус к цене контрабандных товаров.\r\n57. Искуственная жизнь пиратов. Добавлены десять известных пиратов, которых можно будет встретить по игре. Список ситуаций, в которых участвуют эти пираты:\r\n58.1. Можно встретить в таверне.\r\n58.2. Можно встретить в море, у какого либо острова.\r\n58.3. Пират может напасть на главного героя в море.\r\n58.4. О каком-либо действии какого-либо пирата можно случайно узнать у прохожих или отдыхающих в тавернах.\r\n59. Возможность служить губернатору доступна только после завершения сюжетной линии!\r\n60. Добавлены кирасы. Чтобы их экипировать, необходимо иметь способность "Кирасы", а также требуемый ранг.\r\n61. Возможность вымогания денег. Работает в следующем порядке: При разговоре с алкашами в таверне, они могут проболтаться, что у одного из основных жителей колонии водятся большие деньги. И уже непосредственно идём к разбогатевшему хозяину таверны, магазина, верфи, или ростовщику. Шанс, что вам удасться выбить деньги зависит от ранга и вашей удачи и авторитета. В зависимости от этого испытуемый может позвать охрану, ничего не дать, или всё таки дать деньги.\r\n62. Всё холодное оружие разделено на лёгкое, среднее и тяжёлое. В зависимости от типа холодного оружия будет определятся наносимый урон, а также и расходуемая энергия.\r\n63. У любого хозяина таверны можно узнать очень интересную информацию. Естественно, не бесплатно. Причём информация может быть трёх видов. Возможность получить информацию зависит опять же, от удачи и авторитета.\r\n64. Добавлено множество музыки из игры "Пираты Карибского Моря", а также пара звуков.\r\n65. Случайное место начала игры. Генерируется в зависимости от выбранной нации.\r\n66. Выбранная нация при начале новой игры влияет только на начальное местоположение игрока.\r\n67. Иконки предметов преобразились.\r\n68. Тюрьмы теперь оправдывают своё название, т.к. теперь в них находятся заключённые. Это что то вроде декорации.\r\n69. В городах появились проводники, которые за грош могут проводить вас до нужного вам здания.\r\n70. В интерфейсе торговли предметами используйте вспомогательные клавиши для быстрой продажи или покупки товаров. "Alt" работает с 50 единицами, а "Shift" - со всем доступным товаром. Внимание - Только для продажи!\r\n71. Возможность пройтись по своему кораблю. При этом в трюме и пушечной палубе будет расхаживать ваши канониры и матросы, создающие необходимую атмосферу на корабле.\r\n... И ДРУГОЕ![/spoiler]\r\n\r\n[b]Установка и запуск:[/b]\r\n1.- Распаковать игру в нужную Вам директорию.\r\n2.- Играть.', '6030.jpg', '6030.jpg', 32, 2106451619, '2009-06-07 22:50:14', 'single', 1, 0, 0, 2, 0, 0, 0, '2009-06-07 22:50:14', '0000-00-00 00:00:00', 'no', 'no', 1845, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, '', 0, 0, 'no', 0, '', 1, 6, 70, 'http://announce.freeexchange.ru:2710/announce', 'announce.freeexchange.ru:6:70', 1);
INSERT INTO `torrents` (`id`, `info_hash`, `name`, `filename`, `save_as`, `search_text`, `descr`, `ori_descr`, `image1`, `image2`, `category`, `size`, `added`, `type`, `numfiles`, `comments`, `views`, `hits`, `times_completed`, `leechers`, `seeders`, `last_action`, `last_reseed`, `visible`, `banned`, `owner`, `free`, `sticky`, `points`, `silverload`, `image3`, `image4`, `comment_lock`, `ontop`, `ratio`, `tags`, `ratingsum`, `numratings`, `moderated`, `moderatedby`, `moderatorname`, `multitracker`, `f_peers`, `f_seeders`, `announce_list`, `tracker_cache`, `karma`) VALUES (604, 0x32643630323466306130616566656634666561336534646532353039323962383063333464306264, 'Ashampoo Burning Studio 9.03 Final Rus Silent Install', '[OpenSharing.Ru]Ashampoo.Burning.Studio.9.03[SHITUFNET.UA].exe.torrent', 'Ashampoo.Burning.Studio.9.03[SHITUFNET.UA].exe', 'OpenSharing Ru Ashampoo Burning Studio 9 03 SHITUFNET UA exe Ashampoo Burning Studio 9 03 SHITUFNET UA exe Ashampoo Burning Studio 9 03 Final Rus Silent Install', '[u]Информация о Софте[/u]\r\n[b]Название: [/b]Ashampoo Burning Studio 9.03 Final Rus Silent Install\r\n[b]Категория: [/b]Запись\r\n[b]Разработчик:[/b] Ashampoo\r\n[b]Год выпуска: [/b]2009\r\n\r\n[b]О программе: [/b]Ashampoo Burning Studio - новая версия программы для записи CD-RW, DVD-RW, DVD RW и Blu-ray дисков предыдущей линейки пакета. Утилита позволяет создавать проекты и записывать CD/DVD (в том числе MP3-CD, VCD, S-VCD и Blu-ray). Программа поддерживает длинные имена файлов (127 знаков для DVD и Blu-ray и 64 для CD), автоматическую настройку параметров, сохранение и загрузку проекта, создание образов, простое управление файлами с помощью DragandDrop и многое другое.\r\n\r\nС самого первого выпуска Ashampoo Burning Studio 9 изменила представление о привычном программном обеспечении для записи. Вместо того, чтобы тратить время на подробное изучение сотни сложных свойств, вам надо всего лишь выбрать задание, например - «Записать файлы», «Дублировать файлы» или «Записать фильм», а затем программа поможет вам сделать все необходимое. Вы всего лишь выбираете нужный формат, файлы, и записываете диск. Это легко, но легкость не означает, что у вас меньше функциональных возможностей: усовершенствованные функции записи доступны и опытным пользователям, которые хотели бы выбрать специфические системные файлы или воспользоваться специальной областью начальной загрузки.\r\n\r\n[b]Особенности программы:[/b]\r\n- записывайте видео непосредственно с любых видео файлов;\r\n- добавляйте дополнительные файлы, копируя диски, создавайте модифицированные копии загрузочных дисков;\r\n- конвертируйте MP3 файлы так же легко как WMA и WAV;\r\n- выбирайте размер архива, восстанавливайте отдельные файлы;\r\n- создавайте загрузочные диски из области начальной загрузки, выбирайте настройки файловой системы;\r\n- создавайте звуковые компакт-диски из файлов формата MP3, WAV, FLAC, WMA и Ogg Vorbis;\r\n- мультидисковое резервирование файлов и их восстановление на CD/DVD/Blu-ray с компрессией и защитой-паролем;\r\n- быстрое уничтожение и перезапись мультимедиа;\r\n- сохранение дисковых изображений размером больше, чем 2 GB, на файловых системах FAT32;\r\n- интерактивный помощник по диагностике неисправностей и решению проблем с аппаратным обеспечением и носителями;\r\n- сохраняйте файлы проекта для последующей перезаписи;\r\n- встроенная поддержка для мультисессионных записей с возможностью записи свыше 1700 сессий;\r\n- теперь вы можете использовать для ваших дисков видеофайлы Apple QuickTime;\r\n- создавайте из ваших снимков потрясающие DVD-слайдшоу с анимированными графическими меню.\r\n- и многое другое...\r\n\r\n[u]О файле:[/u]\r\n[b]Активация|рег код:[/b] не нужна (автоустановка)\r\n[b]Язык Интерфейса: [/b]Multilingual (русский есть)\r\n\r\n[spoiler=[color=#3333FF]Скриншот интерфейса.[/color]]\r\n[img]http://img2.immage.de/300530dsfsdf.jpg[/img][/spoiler]\r\n', '[u]Информация о Софте[/u]\r\n[b]Название: [/b]Ashampoo Burning Studio 9.03 Final Rus Silent Install\r\n[b]Категория: [/b]Запись\r\n[b]Разработчик:[/b] Ashampoo\r\n[b]Год выпуска: [/b]2009\r\n\r\n[b]О программе: [/b]Ashampoo Burning Studio - новая версия программы для записи CD-RW, DVD-RW, DVD RW и Blu-ray дисков предыдущей линейки пакета. Утилита позволяет создавать проекты и записывать CD/DVD (в том числе MP3-CD, VCD, S-VCD и Blu-ray). Программа поддерживает длинные имена файлов (127 знаков для DVD и Blu-ray и 64 для CD), автоматическую настройку параметров, сохранение и загрузку проекта, создание образов, простое управление файлами с помощью DragandDrop и многое другое.\r\n\r\nС самого первого выпуска Ashampoo Burning Studio 9 изменила представление о привычном программном обеспечении для записи. Вместо того, чтобы тратить время на подробное изучение сотни сложных свойств, вам надо всего лишь выбрать задание, например - «Записать файлы», «Дублировать файлы» или «Записать фильм», а затем программа поможет вам сделать все необходимое. Вы всего лишь выбираете нужный формат, файлы, и записываете диск. Это легко, но легкость не означает, что у вас меньше функциональных возможностей: усовершенствованные функции записи доступны и опытным пользователям, которые хотели бы выбрать специфические системные файлы или воспользоваться специальной областью начальной загрузки.\r\n\r\n[b]Особенности программы:[/b]\r\n- записывайте видео непосредственно с любых видео файлов;\r\n- добавляйте дополнительные файлы, копируя диски, создавайте модифицированные копии загрузочных дисков;\r\n- конвертируйте MP3 файлы так же легко как WMA и WAV;\r\n- выбирайте размер архива, восстанавливайте отдельные файлы;\r\n- создавайте загрузочные диски из области начальной загрузки, выбирайте настройки файловой системы;\r\n- создавайте звуковые компакт-диски из файлов формата MP3, WAV, FLAC, WMA и Ogg Vorbis;\r\n- мультидисковое резервирование файлов и их восстановление на CD/DVD/Blu-ray с компрессией и защитой-паролем;\r\n- быстрое уничтожение и перезапись мультимедиа;\r\n- сохранение дисковых изображений размером больше, чем 2 GB, на файловых системах FAT32;\r\n- интерактивный помощник по диагностике неисправностей и решению проблем с аппаратным обеспечением и носителями;\r\n- сохраняйте файлы проекта для последующей перезаписи;\r\n- встроенная поддержка для мультисессионных записей с возможностью записи свыше 1700 сессий;\r\n- теперь вы можете использовать для ваших дисков видеофайлы Apple QuickTime;\r\n- создавайте из ваших снимков потрясающие DVD-слайдшоу с анимированными графическими меню.\r\n- и многое другое...\r\n\r\n[u]О файле:[/u]\r\n[b]Активация|рег код:[/b] не нужна (автоустановка)\r\n[b]Язык Интерфейса: [/b]Multilingual (русский есть)\r\n\r\n[spoiler=[color=#3333FF]Скриншот интерфейса.[/color]]\r\n[img]http://img2.immage.de/300530dsfsdf.jpg[/img][/spoiler]\r\n', '6040.jpg', '6040.jpg', 33, 60104079, '2009-06-07 22:52:24', 'single', 1, 0, 0, 1, 0, 0, 0, '2009-06-07 22:52:24', '0000-00-00 00:00:00', 'no', 'no', 14, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, 'Запись', 0, 0, 'no', 0, '', 1, 4, 175, 'http://announce.opensharing.ru:2710/announce\nhttp://announce.freeexchange.ru:2710/announce', 'announce.opensharing.ru:2:83\nannounce.freeexchange.ru:2:92', 0),
(605, 0x31616433356562313234633063656333666439616465383765643831356333373837363337323437, 'Autodesk 3D Studio Max 2010 (x86/x64)', '[OpenSharing.Ru]3DSO.torrent', '3DSO[SHITUF.NET.UA]', 'OpenSharing Ru 3DSO 3DSO SHITUF NET UA Autodesk 3D Studio Max 2010 x86 x64', '[u]Информация[/u]\r\n[b]Название:[/b] Autodesk 3D Studio Max 2010 (x86|x64) - Full DVD-Retail\r\n[b]Категория:[/b] 3d моделирование\r\n[b]Разработчик: [/b]Autodesk\r\n[b]Год выпуска:[/b] 2009\r\n[b]Версия: [/b]2010 (v12.0)\r\n\r\n[b]Описание:[/b] Программа Autodesk 3ds Max 2010 позволяет быстро создавать реалистичные персонажи, удачные спецэффекты, захватывающие компьютерные игры, а также высококачественные фильмы и телепрограммы. Усовершенствованные наборы инструментов позволяют формировать 3D окружение в соответствии с вашими потребностями, управлять сложными сценами и использовать все преимущества возросшей функциональной совместимости и поддержки интегрированного процесса разработки.\r\n\r\nС Autodesk 3ds Max 2010 вы сможете создавать впечатляющие 3D модели за меньшее время. Это полнофункциональное решение для 3D моделирования, анимации и рендеринга применяется при разработке самых популярных игр, съемке фильмов и видеопрограмм.\r\n\r\n[spoiler=[b]Функциональные возможности:[/b]]\r\n* Пользовательский интерфейс 3ds Max\r\n* Управление данными и сценами\r\n* Моделирование\r\n* Полигональное моделирование и текстурирование\r\n* Моделирование сплайнов\r\n* Общая анимация\r\n* Анимация персонажей\r\n* Модификаторы\r\n* Объемные деформации\r\n* Динамика\r\n* Одежда\r\n* Частицы\r\n* Комбинированный рендеринг\r\n* Управление рендерингом и создание специальных эффектов\r\n* Меховой и волосяной покров\r\n* ProSound\r\n* MAXScript\r\n\r\nСреди новых технологий визуализации можно отметить набор инструментов Reveal™, предназначенный для итерационной подготовки и более быстрого выполнения рендеринга, а также библиотеку материалов ProMaterials™, позволяющую имитировать реальные поверхности. Новая процедура моделирования живых существ даст вам возможность быстрее и эффективнее встраивать в проекты изображения людей и животных. Применение функции «Hands like feet» и множества других новых и улучшенных процедур для анимации персонажей и мэпинга рационализирует потенциально трудоемкие процессы. В новой версии улучшены импорт и экспорт в OBJ и Autodesk® FBX®, что значительно повышает степень взаимодействия 3ds Max с Autodesk® Mudbox™, Maya, Autodesk® MotionBuilder™ и приложениями сторонних разработчиков.\r\n\r\nПодробности — на странице с детальным описанием возможностей. \r\n\r\nНовые и усовершенствованные функции:\r\n\r\nВ новой версии представлено огромное число нововведений и улучшений. Их количество настолько велико, что создатели 3ds Max говорят о том, что это – самый значительный релиз, начиная с версии 3D Studio Max 4. Пожалуй, одно из наиболее заметных нововведений – включение в состав программы популярного набора инструментов для моделирования PolyBoost, которые ранее были доступны в виде дополнения. В 3ds Max эти средства появятся под названием Graphite Modeling Tools. Благодаря PolyBoost, в общей сложности, в новой версии появится более 100 новых инструментов. Кроме Graphite Modeling Tools, в 3ds Max 2010 представлено около трехсот нововведений. Вот лишь некоторые из них:\r\n* Организация сложных сцен посредством объединения ее объектов в так называемые контейнеры (Container). Такими объектами легко управлять, их можно быстро загружать и выгружать, тем самым экономя затраты оперативной памяти.\r\n* Улучшенное отображение объектов в окнах проекций, сглаживание с использованием аппаратных возможностей ПК, улучшенные средства для работы с HDRI и поддержка технологии новой mental mill для разработки шейдеров.\r\n* Новый модуль Material Explorer для управления материалами сцены, позволяющий выполнять операции с материалами по отношению к нескольким объектам, в том числе заменять их.\r\n* Улучшенная поддержка импорта моделей из Revit Architecture.\r\n* Новая технология xView для анализа сетки трехмерных моделей\r\n* Новая версия модуля для создания эффектов с частицами PFlowAdvanced, содержащая большую библиотеку готовых эффектов. PFlowAdvanced включает 14 новых операторов для Particle Flow.\r\n* Набор инструментов для работы со звуком ProSound, в основе которого плагин Sound Trax от компании Boomer Labs.\r\n* Новый модификатор Quadify для работы с модулем ProBooleans, позволяющий управлять топологией булевых объектов. Кроме этого, при работе с ProBooleans теперь можно использовать операцию Merge Boolean, которая позволяет объединять объекты, сохраняя их топологию и стеки модификаторов.\r\n* Новый модификатор ProOptimizer, который создан на основе известного дополнения Polygon Cruncher. С его помощью можно выполнять оптимизацию высокополигональных моделей, импортированных из программ наподобие Mudbox.\r\n* Улучшения в наборе инструментов для работы с текстурными развертками. В частности, добавлены новые инструменты для выделения, а также для редактирования разверток.\r\n* Новое средство для анализа эффектов, связанных со светом, и предпросмотра результатов в окне проекции (только в 3ds Max Design 2010).\r\n* Global Quality Knobs для быстрого управления качеством визуализации теней, отражений, преломлений, а также просчета глобального освещения и сглаживания в mental ray.\r\n* Поддержка визуализации изображений большого разрешения для использования в полиграфии.\r\n* Улучшения в визуализации анимационных проектов средствами mental ray (уменьшение ошибок, связанных с мерцанием при воспроизведении анимации, которая была просчитана с учетом непрямого освещения).[/spoiler]\r\n\r\n[u]Системные требования:[/u]\r\n\r\nДля установки и работы Autodesk® 3ds Max® 2010 требуется одна из следующих 32- или 64-разрядных операционных систем:\r\nMicrosoft® Windows® XP Professional (пакет обновления SP2 или более поздний).\r\nMicrosoft® Windows® Vista (Business, Premium или Ultimate).\r\nMicrosoft® Windows® XP Professional x64.\r\nMicrosoft® Windows® Vista 64 bit (Business, Premium или Ultimate).\r\nДля работы 3ds Max 2010 должен быть установлен следующий браузер:\r\nMicrosoft® Internet Explorer® 6 или более поздней версии.\r\n\r\nДля работы 3ds Max 2010 требуется следующее дополнительное программное обеспечение:\r\nDirectX® 9.0c* (требуется для работы), OpenGL® (по желанию пользователя).\r\n*Некоторые функции 3ds Max 2010 доступны только в случае, когда графическое оборудование поддерживает Shader Model 3.0 (Pixel Shader и Vertex Shader 3.0). За информацией о том, поддерживает ли конкретное устройство Shader Model 3.0, следует обращаться к его изготовителю.\r\n\r\n[u]Требования к аппаратному обеспечению:[/u]\r\nМинимальным требованиям 32-разрядной версии 3ds Max 2010 удовлетворяет компьютер со следующей конфигурацией:\r\n- Процессор Intel Pentium® 4 или выше, AMD Athlon® 64 или выше, либо AMD Opteron®.\r\n- 1 Гб оперативной памяти (рекомендуется 2 Гб).\r\n- 1 Гб в файле подкачки (рекомендуется 2 Гб).\r\n- Графический адаптер со 128 Мб памяти или больше, поддерживающий Direct3D 10, Direct3D 9 или OpenGL.\r\n- Трехкнопочная мышь с драйвером.\r\n- 2 Гб на жестком диске.\r\n- Привод DVD-ROM.\r\n\r\n[b]Язык Интерфейса: [/b]только английский\r\n[b]Платформа/ОС:[/b] Windows All 32/64 bit (сертифицировано)\r\n[b]Совместимость с Vista:[/b] полная\r\n[b]Таблетка: [/b]присутствует (Keygen or *.dll)\r\n[b]Формат файла:[/b] iso\r\n[b]MD5 ISO:[/b] b71ee659a86179df7010949363b33ec8\r\n\r\n[b]УСТАНОВКА:[/b]\r\n1. Распаковать. Прожечь на диск или смонтировать в виртуальный привод.\r\n2. Установить (используя Keygen / серийный номер) = читать install.txt в архиве с Кейгеном!\r\n3. Enjoy!\r\n', '[u]Информация[/u]\r\n[b]Название:[/b] Autodesk 3D Studio Max 2010 (x86|x64) - Full DVD-Retail\r\n[b]Категория:[/b] 3d моделирование\r\n[b]Разработчик: [/b]Autodesk\r\n[b]Год выпуска:[/b] 2009\r\n[b]Версия: [/b]2010 (v12.0)\r\n\r\n[b]Описание:[/b] Программа Autodesk 3ds Max 2010 позволяет быстро создавать реалистичные персонажи, удачные спецэффекты, захватывающие компьютерные игры, а также высококачественные фильмы и телепрограммы. Усовершенствованные наборы инструментов позволяют формировать 3D окружение в соответствии с вашими потребностями, управлять сложными сценами и использовать все преимущества возросшей функциональной совместимости и поддержки интегрированного процесса разработки.\r\n\r\nС Autodesk 3ds Max 2010 вы сможете создавать впечатляющие 3D модели за меньшее время. Это полнофункциональное решение для 3D моделирования, анимации и рендеринга применяется при разработке самых популярных игр, съемке фильмов и видеопрограмм.\r\n\r\n[spoiler=[b]Функциональные возможности:[/b]]\r\n* Пользовательский интерфейс 3ds Max\r\n* Управление данными и сценами\r\n* Моделирование\r\n* Полигональное моделирование и текстурирование\r\n* Моделирование сплайнов\r\n* Общая анимация\r\n* Анимация персонажей\r\n* Модификаторы\r\n* Объемные деформации\r\n* Динамика\r\n* Одежда\r\n* Частицы\r\n* Комбинированный рендеринг\r\n* Управление рендерингом и создание специальных эффектов\r\n* Меховой и волосяной покров\r\n* ProSound\r\n* MAXScript\r\n\r\nСреди новых технологий визуализации можно отметить набор инструментов Reveal™, предназначенный для итерационной подготовки и более быстрого выполнения рендеринга, а также библиотеку материалов ProMaterials™, позволяющую имитировать реальные поверхности. Новая процедура моделирования живых существ даст вам возможность быстрее и эффективнее встраивать в проекты изображения людей и животных. Применение функции «Hands like feet» и множества других новых и улучшенных процедур для анимации персонажей и мэпинга рационализирует потенциально трудоемкие процессы. В новой версии улучшены импорт и экспорт в OBJ и Autodesk® FBX®, что значительно повышает степень взаимодействия 3ds Max с Autodesk® Mudbox™, Maya, Autodesk® MotionBuilder™ и приложениями сторонних разработчиков.\r\n\r\nПодробности — на странице с детальным описанием возможностей. \r\n\r\nНовые и усовершенствованные функции:\r\n\r\nВ новой версии представлено огромное число нововведений и улучшений. Их количество настолько велико, что создатели 3ds Max говорят о том, что это – самый значительный релиз, начиная с версии 3D Studio Max 4. Пожалуй, одно из наиболее заметных нововведений – включение в состав программы популярного набора инструментов для моделирования PolyBoost, которые ранее были доступны в виде дополнения. В 3ds Max эти средства появятся под названием Graphite Modeling Tools. Благодаря PolyBoost, в общей сложности, в новой версии появится более 100 новых инструментов. Кроме Graphite Modeling Tools, в 3ds Max 2010 представлено около трехсот нововведений. Вот лишь некоторые из них:\r\n* Организация сложных сцен посредством объединения ее объектов в так называемые контейнеры (Container). Такими объектами легко управлять, их можно быстро загружать и выгружать, тем самым экономя затраты оперативной памяти.\r\n* Улучшенное отображение объектов в окнах проекций, сглаживание с использованием аппаратных возможностей ПК, улучшенные средства для работы с HDRI и поддержка технологии новой mental mill для разработки шейдеров.\r\n* Новый модуль Material Explorer для управления материалами сцены, позволяющий выполнять операции с материалами по отношению к нескольким объектам, в том числе заменять их.\r\n* Улучшенная поддержка импорта моделей из Revit Architecture.\r\n* Новая технология xView для анализа сетки трехмерных моделей\r\n* Новая версия модуля для создания эффектов с частицами PFlowAdvanced, содержащая большую библиотеку готовых эффектов. PFlowAdvanced включает 14 новых операторов для Particle Flow.\r\n* Набор инструментов для работы со звуком ProSound, в основе которого плагин Sound Trax от компании Boomer Labs.\r\n* Новый модификатор Quadify для работы с модулем ProBooleans, позволяющий управлять топологией булевых объектов. Кроме этого, при работе с ProBooleans теперь можно использовать операцию Merge Boolean, которая позволяет объединять объекты, сохраняя их топологию и стеки модификаторов.\r\n* Новый модификатор ProOptimizer, который создан на основе известного дополнения Polygon Cruncher. С его помощью можно выполнять оптимизацию высокополигональных моделей, импортированных из программ наподобие Mudbox.\r\n* Улучшения в наборе инструментов для работы с текстурными развертками. В частности, добавлены новые инструменты для выделения, а также для редактирования разверток.\r\n* Новое средство для анализа эффектов, связанных со светом, и предпросмотра результатов в окне проекции (только в 3ds Max Design 2010).\r\n* Global Quality Knobs для быстрого управления качеством визуализации теней, отражений, преломлений, а также просчета глобального освещения и сглаживания в mental ray.\r\n* Поддержка визуализации изображений большого разрешения для использования в полиграфии.\r\n* Улучшения в визуализации анимационных проектов средствами mental ray (уменьшение ошибок, связанных с мерцанием при воспроизведении анимации, которая была просчитана с учетом непрямого освещения).[/spoiler]\r\n\r\n[u]Системные требования:[/u]\r\n\r\nДля установки и работы Autodesk® 3ds Max® 2010 требуется одна из следующих 32- или 64-разрядных операционных систем:\r\nMicrosoft® Windows® XP Professional (пакет обновления SP2 или более поздний).\r\nMicrosoft® Windows® Vista (Business, Premium или Ultimate).\r\nMicrosoft® Windows® XP Professional x64.\r\nMicrosoft® Windows® Vista 64 bit (Business, Premium или Ultimate).\r\nДля работы 3ds Max 2010 должен быть установлен следующий браузер:\r\nMicrosoft® Internet Explorer® 6 или более поздней версии.\r\n\r\nДля работы 3ds Max 2010 требуется следующее дополнительное программное обеспечение:\r\nDirectX® 9.0c* (требуется для работы), OpenGL® (по желанию пользователя).\r\n*Некоторые функции 3ds Max 2010 доступны только в случае, когда графическое оборудование поддерживает Shader Model 3.0 (Pixel Shader и Vertex Shader 3.0). За информацией о том, поддерживает ли конкретное устройство Shader Model 3.0, следует обращаться к его изготовителю.\r\n\r\n[u]Требования к аппаратному обеспечению:[/u]\r\nМинимальным требованиям 32-разрядной версии 3ds Max 2010 удовлетворяет компьютер со следующей конфигурацией:\r\n- Процессор Intel Pentium® 4 или выше, AMD Athlon® 64 или выше, либо AMD Opteron®.\r\n- 1 Гб оперативной памяти (рекомендуется 2 Гб).\r\n- 1 Гб в файле подкачки (рекомендуется 2 Гб).\r\n- Графический адаптер со 128 Мб памяти или больше, поддерживающий Direct3D 10, Direct3D 9 или OpenGL.\r\n- Трехкнопочная мышь с драйвером.\r\n- 2 Гб на жестком диске.\r\n- Привод DVD-ROM.\r\n\r\n[b]Язык Интерфейса: [/b]только английский\r\n[b]Платформа/ОС:[/b] Windows All 32/64 bit (сертифицировано)\r\n[b]Совместимость с Vista:[/b] полная\r\n[b]Таблетка: [/b]присутствует (Keygen or *.dll)\r\n[b]Формат файла:[/b] iso\r\n[b]MD5 ISO:[/b] b71ee659a86179df7010949363b33ec8\r\n\r\n[b]УСТАНОВКА:[/b]\r\n1. Распаковать. Прожечь на диск или смонтировать в виртуальный привод.\r\n2. Установить (используя Keygen / серийный номер) = читать install.txt в архиве с Кейгеном!\r\n3. Enjoy!\r\n', '6050.jpg', '6050.jpg', 33, 3841545206, '2009-06-07 22:57:06', 'multi', 3, 0, 0, 0, 0, 0, 0, '2009-06-07 22:57:06', '0000-00-00 00:00:00', 'no', 'no', 14, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, 'Моделирование,3D', 0, 0, 'no', 0, '', 1, 12, 17, 'http://announce.opensharing.ru:2710/announce\nhttp://announce.freeexchange.ru:2710/announce', 'announce.opensharing.ru:12:17\nannounce.freeexchange.ru:0:0', 1),
(606, 0x35636433663361343732383036303432393033386561323336336663333639346530623935333636, 'Logic Studio 8 (2007) Mac OS', '[OpenSharing.Ru]Logic_Studio_8.0.torrent', 'Logic Studio 8.0', 'OpenSharing Ru Logic Studio 8 0 Logic Studio 8 0 Logic Studio 8 2007 Mac OS', '[b]Год выпуска: [/b] 2007\r\n[b]Версия:[/b] 8.0\r\n[b]Разработчик:[/b] Apple Inc.\r\n[b]Платформа: [/b]PPC/Intel universal\r\n[b]Язык интерфейса: [/b]Только английский\r\n[b]Таблетка: [/b]Присутствует\r\n\r\n[b]Описание:[/b]\r\nLogic Studio — новый пакет программ для работы со звуком, который по уровню интеграции компонентов выполнен в лучших традициях Final Cut Studio. Теперь как и его видео аналог, Logic Studio не будет требовать USB-ключа для активации.\r\n\r\nВ состав пакета вошли такие компоненты, как Logic Pro 8, MainStage для проведения «живых» концертов и аранжировок, приложение создания аудиодорожек для проектов видео Soundtrack 2, а также коллекции из 40 музыкальных инструментов, 80 эффектов, аудиосэмплов и ряд дополнительных утилит.\r\n\r\n[u]Системные требования:[/u]\r\n\r\nMac system with a 1.25GHz or faster PowerPC G4 processor (PowerPC G5, Intel Core Duo, or Intel Xeon processor highly)\r\n\r\n1GB of RAM (2GB or more highly recommended)\r\n\r\nDisplay with 1024-by-768 resolution (1280-by-800 or higher recommended)\r\n\r\nMac OS X v10.4.9 or later\r\n\r\nQuickTime 7.2 or later\r\n\r\nDVD drive for installation\r\n\r\nPCI Express, ExpressCard/34, USB, or FireWire based audio interface recommended\r\n', '[b]Год выпуска: [/b] 2007\r\n[b]Версия:[/b] 8.0\r\n[b]Разработчик:[/b] Apple Inc.\r\n[b]Платформа: [/b]PPC/Intel universal\r\n[b]Язык интерфейса: [/b]Только английский\r\n[b]Таблетка: [/b]Присутствует\r\n\r\n[b]Описание:[/b]\r\nLogic Studio — новый пакет программ для работы со звуком, который по уровню интеграции компонентов выполнен в лучших традициях Final Cut Studio. Теперь как и его видео аналог, Logic Studio не будет требовать USB-ключа для активации.\r\n\r\nВ состав пакета вошли такие компоненты, как Logic Pro 8, MainStage для проведения «живых» концертов и аранжировок, приложение создания аудиодорожек для проектов видео Soundtrack 2, а также коллекции из 40 музыкальных инструментов, 80 эффектов, аудиосэмплов и ряд дополнительных утилит.\r\n\r\n[u]Системные требования:[/u]\r\n\r\nMac system with a 1.25GHz or faster PowerPC G4 processor (PowerPC G5, Intel Core Duo, or Intel Xeon processor highly)\r\n\r\n1GB of RAM (2GB or more highly recommended)\r\n\r\nDisplay with 1024-by-768 resolution (1280-by-800 or higher recommended)\r\n\r\nMac OS X v10.4.9 or later\r\n\r\nQuickTime 7.2 or later\r\n\r\nDVD drive for installation\r\n\r\nPCI Express, ExpressCard/34, USB, or FireWire based audio interface recommended\r\n', '6060.jpg', '6060.jpg', 33, 50385551916, '2009-06-07 23:06:36', 'multi', 10, 0, 0, 0, 0, 0, 0, '2009-06-07 23:06:36', '0000-00-00 00:00:00', 'no', 'no', 14, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, 'Звук', 0, 0, 'no', 0, '', 1, 5, 3, 'http://open.tracker.thepiratebay.org/announce\nhttp://announce.opensharing.ru:2710/announce', 'open.tracker.thepiratebay.org:3:1\nannounce.opensharing.ru:2:2', 0),
(607, 0x36356431613035353537363331323036316461383534346230336564623639643236643466313565, 'Adobe Dreamweaver CS4 / 2008 / PC', '[OpenSharing.Ru]Adobe.Dreamweaver.CS4.2008.PC.torrent', 'Adobe.Dreamweaver.CS4.2008.PC', 'OpenSharing Ru Adobe Dreamweaver CS4 2008 PC Adobe Dreamweaver CS4 2008 PC Adobe Dreamweaver CS4 2008 PC', '[b]Оригинальное название:[/b] Adobe Dreamweaver CS4\r\n[b]Версия: [/b]10 build 4117 [Retail]\r\n[b]Год выпуска: [/b]2008\r\n[b]Разработчик: [/b]Adobe Systems Incorporated\r\n[b]Язык:[/b] Английский, испанский, французский\r\n\r\n[b]О программе: [/b]Adobe Dreamweaver включает самые прогрессивные возможности и технологии, с помощью которых можно создавать динамичные и современные веб-сайты, соответствующие сегодняшним стандартам. Данное приложение позволяет не только с легкостью проектировать дизайн сайта, используя визуальные методы, но и предоставляет необходимые средства для продуктивной разработки веб-приложений. Тут присутствует полная поддержка формата CSS, с функцией проверки его совместимости с различными браузерами, функциональный редактор кода веб-страниц и возможность работать с такими технологиями, как: XML, JavaScript, PHP, Adobe ColdFusion, ASP и ASP.NET. В новой версии появилась среда для разработки Ajax-приложений, которые могут выполнять самые разные функции (получение информации из RSS каналов и баз данных, создание визуальных эффектов и многое другое), добавлена возможность создания сайтов на основе тегов DIV, реализована тесная интеграция с другими программами Adobe.\r\n\r\n[u]Примечание: Лекарство в комплекте.[/u]\r\n\r\n[b]Установка:[/b]\r\n1. Распаковываем архив. Для этого запускаем DRWVCS4_Cont_LS1.exe и указываем любую временную папку.\r\n2. Переходим во временую папку запускаем ADBEDRWVCS4_LS1.exe для установки приложения.\r\n3. При установке выбраем триальный режим без ввода ключа, расположен правее от режима с вводом ключика.\r\n4. После установки активзируем триальный режимю Для этого запускаем Adobe Dreamweaver CS4. Посое появления окна с предупреждением, что срок использования в триальном режиме 30 дней, и предложением ввести ключ закрываем программу\r\n5. Копируем amtlib.dll из папки nope, она входит в раздачу, в папку, куда был установлен Dreamweaver CS4 с заменой файлов. Предварительно желательно сделать копию оригинального файла.\r\n6. Все, пользуемся приложением.\r\n\r\n[b]Минимальные системные требования:[/b]\r\nОперационная система: Windows XP SP2/Vista SP1\r\nПроцессор: Pentium III 1 ГГц\r\nПамять: 512 МБ\r\nВидеокарта: 16 бит, 1280x800\r\nСвободное место на ЖД: 1 ГБ\r\nРазмер: 349.21 МБ (366,177,716 байт)\r\n', '[b]Оригинальное название:[/b] Adobe Dreamweaver CS4\r\n[b]Версия: [/b]10 build 4117 [Retail]\r\n[b]Год выпуска: [/b]2008\r\n[b]Разработчик: [/b]Adobe Systems Incorporated\r\n[b]Язык:[/b] Английский, испанский, французский\r\n\r\n[b]О программе: [/b]Adobe Dreamweaver включает самые прогрессивные возможности и технологии, с помощью которых можно создавать динамичные и современные веб-сайты, соответствующие сегодняшним стандартам. Данное приложение позволяет не только с легкостью проектировать дизайн сайта, используя визуальные методы, но и предоставляет необходимые средства для продуктивной разработки веб-приложений. Тут присутствует полная поддержка формата CSS, с функцией проверки его совместимости с различными браузерами, функциональный редактор кода веб-страниц и возможность работать с такими технологиями, как: XML, JavaScript, PHP, Adobe ColdFusion, ASP и ASP.NET. В новой версии появилась среда для разработки Ajax-приложений, которые могут выполнять самые разные функции (получение информации из RSS каналов и баз данных, создание визуальных эффектов и многое другое), добавлена возможность создания сайтов на основе тегов DIV, реализована тесная интеграция с другими программами Adobe.\r\n\r\n[u]Примечание: Лекарство в комплекте.[/u]\r\n\r\n[b]Установка:[/b]\r\n1. Распаковываем архив. Для этого запускаем DRWVCS4_Cont_LS1.exe и указываем любую временную папку.\r\n2. Переходим во временую папку запускаем ADBEDRWVCS4_LS1.exe для установки приложения.\r\n3. При установке выбраем триальный режим без ввода ключа, расположен правее от режима с вводом ключика.\r\n4. После установки активзируем триальный режимю Для этого запускаем Adobe Dreamweaver CS4. Посое появления окна с предупреждением, что срок использования в триальном режиме 30 дней, и предложением ввести ключ закрываем программу\r\n5. Копируем amtlib.dll из папки nope, она входит в раздачу, в папку, куда был установлен Dreamweaver CS4 с заменой файлов. Предварительно желательно сделать копию оригинального файла.\r\n6. Все, пользуемся приложением.\r\n\r\n[b]Минимальные системные требования:[/b]\r\nОперационная система: Windows XP SP2/Vista SP1\r\nПроцессор: Pentium III 1 ГГц\r\nПамять: 512 МБ\r\nВидеокарта: 16 бит, 1280x800\r\nСвободное место на ЖД: 1 ГБ\r\nРазмер: 349.21 МБ (366,177,716 байт)\r\n', '6070.jpg', '6070.jpg', 33, 366177716, '2009-06-07 23:09:38', 'multi', 5, 0, 0, 1, 0, 0, 0, '2009-06-07 23:09:38', '0000-00-00 00:00:00', 'no', 'no', 14, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, 'Adobe', 0, 0, 'no', 0, '', 1, 0, 10, 'http://announce.opensharing.ru:2710/announce\nhttp://kinomonstr.com/announce.php', 'announce.opensharing.ru:0:10\nkinomonstr.com:0:0', 1);
INSERT INTO `torrents` (`id`, `info_hash`, `name`, `filename`, `save_as`, `search_text`, `descr`, `ori_descr`, `image1`, `image2`, `category`, `size`, `added`, `type`, `numfiles`, `comments`, `views`, `hits`, `times_completed`, `leechers`, `seeders`, `last_action`, `last_reseed`, `visible`, `banned`, `owner`, `free`, `sticky`, `points`, `silverload`, `image3`, `image4`, `comment_lock`, `ontop`, `ratio`, `tags`, `ratingsum`, `numratings`, `moderated`, `moderatedby`, `moderatorname`, `multitracker`, `f_peers`, `f_seeders`, `announce_list`, `tracker_cache`, `karma`) VALUES (608, 0x62313463393932303433336661353264373437623865643438643665323633313861343238326630, 'JetAudio 7.1.9 Plus VX(2009)', '[OpenSharing.Ru]jet7.1.9rus.torrent', 'jetaudio7.1.9rus', 'OpenSharing Ru jet7 1 9rus jetaudio7 1 9rus JetAudio 7 1 9 Plus VX 2009', '[b]Год выпуска: [/b]2009\r\n[b]Версия: [/b]7.1.9. Plus VX\r\n[b]Разработчик: [/b]CowonAmerica\r\n[b]Совместимость с Vista: [/b]полная\r\n[b]Язык интерфейса: [/b]русский\r\n[b]Таблетка: [/b]Не требуется\r\nНовейший Language pack for jetAudio можно взять с оф.сайта.   \r\n\r\n[u]JetAudio[/u] — это универсальный проигрыватель музыкальных и видео файлов, риппер, конвертер и т.д., в общем, все в одном комплекте. Программа поддерживает практически  все музыкальный форматы, умеет проигрывать MP3, MP2, WAV, MID, REAL AUDIO/VIDEO, S3M, MOD, MPG, AVI, MOV, Video/Audio CD, RealPlayer G2 и некоторые другие форматы мультимедийных файлов. Позволяет записывать аудио компакт-диски или копировать их содержимое на жесткий диск ПК. Есть возможность накладывать на композиции различные эффекты, поддерживается синхронизация для караоке, имеется эквалайзер, конвертер форматов, редактор тэгов, кроссфейдинг, субтитры и т.д.\r\n\r\n[b]Особенности:[/b]\r\n\r\nдобавлены  полностью русифицированые скины;\r\n\r\nподдержка плагинов визуализации;\r\n\r\nподдержка плагинов визуализации Winamp 2x;\r\n\r\nподдержка плагинов визуализации Sonique;\r\n\r\nесть возможность конвертирования популярных аудио и видео форматов;\r\n\r\nвозможность создать свою интернет радиостанцию;\r\n\r\nподдержка скинов;\r\n\r\nвстроенные кодеки популярных форматов мультимедийных файлов;\r\n\r\nподдержка X-SURROUND (Дополнительное окружение для многоканальных систем).\r\nЧто Нового в jetAudio 7.1.9:\r\n     Исправленные проблемы.\r\n     - PLS файл не запускал воспроизведение, когда он был кликнутый два раза.\r\n     - Исправлены другие незначительные дефекты.\r\n\r\n[b]Системные требования:[/b]\r\nPentium 800 MHz или более быстрый CPU\r\n256MB of RAM (512MB или больше рекомендуется)\r\n40 MB на жестком диске\r\nОС: Windows 98/Me/2000/XP/Vista\r\nЗвуковая карта, колонки или наушники\r\nМикрофон (Опция)\r\nСоединение с Интернет (Опция)\r\nНеобходимые компоненты системы:\r\n DirectX 8 or higher version\r\n QuickTime 4 or higher version (для воспроизведения QuickTime файлов)\r\n', '[b]Год выпуска: [/b]2009\r\n[b]Версия: [/b]7.1.9. Plus VX\r\n[b]Разработчик: [/b]CowonAmerica\r\n[b]Совместимость с Vista: [/b]полная\r\n[b]Язык интерфейса: [/b]русский\r\n[b]Таблетка: [/b]Не требуется\r\nНовейший Language pack for jetAudio можно взять с оф.сайта.   \r\n\r\n[u]JetAudio[/u] — это универсальный проигрыватель музыкальных и видео файлов, риппер, конвертер и т.д., в общем, все в одном комплекте. Программа поддерживает практически  все музыкальный форматы, умеет проигрывать MP3, MP2, WAV, MID, REAL AUDIO/VIDEO, S3M, MOD, MPG, AVI, MOV, Video/Audio CD, RealPlayer G2 и некоторые другие форматы мультимедийных файлов. Позволяет записывать аудио компакт-диски или копировать их содержимое на жесткий диск ПК. Есть возможность накладывать на композиции различные эффекты, поддерживается синхронизация для караоке, имеется эквалайзер, конвертер форматов, редактор тэгов, кроссфейдинг, субтитры и т.д.\r\n\r\n[b]Особенности:[/b]\r\n\r\nдобавлены  полностью русифицированые скины;\r\n\r\nподдержка плагинов визуализации;\r\n\r\nподдержка плагинов визуализации Winamp 2x;\r\n\r\nподдержка плагинов визуализации Sonique;\r\n\r\nесть возможность конвертирования популярных аудио и видео форматов;\r\n\r\nвозможность создать свою интернет радиостанцию;\r\n\r\nподдержка скинов;\r\n\r\nвстроенные кодеки популярных форматов мультимедийных файлов;\r\n\r\nподдержка X-SURROUND (Дополнительное окружение для многоканальных систем).\r\nЧто Нового в jetAudio 7.1.9:\r\n     Исправленные проблемы.\r\n     - PLS файл не запускал воспроизведение, когда он был кликнутый два раза.\r\n     - Исправлены другие незначительные дефекты.\r\n\r\n[b]Системные требования:[/b]\r\nPentium 800 MHz или более быстрый CPU\r\n256MB of RAM (512MB или больше рекомендуется)\r\n40 MB на жестком диске\r\nОС: Windows 98/Me/2000/XP/Vista\r\nЗвуковая карта, колонки или наушники\r\nМикрофон (Опция)\r\nСоединение с Интернет (Опция)\r\nНеобходимые компоненты системы:\r\n DirectX 8 or higher version\r\n QuickTime 4 or higher version (для воспроизведения QuickTime файлов)\r\n', '6080.jpg', '6080.jpg', 33, 28625872, '2009-06-07 23:14:43', 'multi', 4, 0, 0, 1, 0, 0, 0, '2009-06-07 23:14:43', '0000-00-00 00:00:00', 'no', 'no', 14, 0, 'no', 0, 'no', '', '', 'no', 'no', 0, 'Запись,Звук,Конвертер,Проигрыватель', 0, 0, 'no', 0, '', 1, 2, 76, 'http://announce.freeexchange.ru:2710/announce\nhttp://announce.opensharing.ru:2710/announce\nhttp://tracker.prq.to/announce', 'announce.freeexchange.ru:1:40\nannounce.opensharing.ru:1:35\ntracker.prq.to:0:1', 0),
(609, 0x35386162366539323831336434613239333239633130366365623362666134653138336562353364, 'Google Earth Pro / Google Планета Земля (2007) PC', '[OpenSharing.Ru]Google_Earth_Pro_v4.2.180.11.34.torrent', 'Google_Earth_Pro_v4.2.180.11.34', 'OpenSharing Ru Google Earth Pro v4 2 180 11 34 Google Earth Pro v4 2 180 11 34 Google Earth Pro Google 2007 PC', '[b]Операционная система: [/b]Windows® 2000/XP/Vista.\r\n[b]Версия:[/b] Google Earth Pro 4.2.180.11.34\r\n[b]Выпущена: [/b]Aug 20 2007\r\n[b]Язык интерфейса:[/b] Русский.\r\n[b]Лекарство: [/b]Crack.\r\n\r\n[b]Описание:[/b]\r\nGoogle Планета Земля - может перенести вас в любое место на земле для просмотра карт, спутниковых изображений, ландшафта и 3D-зданий и даже предоставляет возможности для исследования галактик и звездного неба. Вы можете изучать географическое содержание, сохранять обзор мест и делиться информацией с другими пользователями.\r\n\r\nС помощью Google Планета Земля Про можно легко изучать географические объекты и отображать найденные вами данные. С помощью нескольких нажатий мыши вы можете импортировать планы местности, списки недвижимости или местоположения клиентов и предоставить совместный доступ к виду вашему клиенту или коллеге. Более того, вы можете экспортировать высококачественные изображения в документы или в Интернет.\r\n\r\n[u]Комментирование и визуализация: [/u]Представляйте ваши данные о местоположении с помощью трехмерных средств рисования или переносите до 2500 объектов по адресу или геопространственным координатам из таблицы. Модуль импорта данных геоинформационной системы (ГИС) позволяет объединять данные ГИС в файлах таких форматов, как .shp и .tab. Примеры включают в себя данные об участке, трехмерных зданиях и демографическую информацию. \r\n\r\n\r\n[b]Доп. информация: [/b]\r\n[u]В папке: [/u]\r\n1.Google Earth Pro.exe (Установочный файл программы.) \r\n2.Crack.exe (кряк) \r\n3.Полная инструкция по установке и лицензивированию в картинках. \r\n\r\n[u]Установка: [/u]\r\n1) Устаналвиаем 